custom_css:
/* 奶油贝壳主题 · 作者 @jiuyi0204 · 未经许可禁止二次修改与二次上传 */

/* ===== src\kernel\safety.css ===== */

/* 奶油贝壳：功能与回退保护。此文件不保存固定构图。 */

:is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) .drawer-icon::after,
#send_form #options_button::after,
#send_form #extensionsMenuButton::after,
#send_form #send_but::after,
#send_form #mes_stop::after,
#send_form #stscript_stop::after {
    pointer-events: none;
}

#top-settings-holder :is(.drawer-toggle, .drawer-icon, .interactable):focus-visible,
#send_form :is(.interactable, .menu_button, textarea):focus-visible,
#chat :is(.mes_button, .menu_button, summary):focus-visible,
:is(#left-nav-panel, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup) :is(button, input, select, textarea, [tabindex]):focus-visible {
    outline: 2px solid var(--cream-shell-focus, #a9c1ce);
    outline-offset: 2px;
}

:is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) .drawer-icon::after,
#send_form #options_button::after,
#send_form #extensionsMenuButton::after,
#send_form #send_but::after,
#send_form #mes_stop::after,
#send_form #stscript_stop::after,
#send_form #nonQRFormItems::before {
    background-repeat: no-repeat;
    background-position: center;
}

@media (prefers-reduced-motion: reduce) {
    #top-settings-holder .drawer-icon,
    #send_form .interactable,
    #chat .mes_buttons {
        transition-duration: 0.01ms;
    }
}


/* ===== src\kernel\scrollbars.css ===== */

/* 隐藏滚动条外观；保留滚轮、触摸、键盘和容器自身 overflow 行为。 */

html,
body,
#sheld,
#sheld *,
#chat,
.drawer-content,
.popup-content,
.scrollable,
.select2-results__options,
#send_textarea,
#chat .mes_text pre,
#chat .mes_text .table-responsive {
    scrollbar-width: none;
    -ms-overflow-style: none;
}

html::-webkit-scrollbar,
body::-webkit-scrollbar,
#sheld::-webkit-scrollbar,
#sheld *::-webkit-scrollbar,
#chat::-webkit-scrollbar,
.drawer-content::-webkit-scrollbar,
.popup-content::-webkit-scrollbar,
.scrollable::-webkit-scrollbar,
.select2-results__options::-webkit-scrollbar,
#send_textarea::-webkit-scrollbar,
#chat .mes_text pre::-webkit-scrollbar,
#chat .mes_text .table-responsive::-webkit-scrollbar {
    width: 0;
    height: 0;
}


/* ===== src\tokens.css ===== */

@font-face {
    font-family: "CreamShellSerif";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/sourcehanserifsc/sourcehanserifsc.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    /* v7 视觉状态合同令牌：所有状态组件直接引用这一组，不继承酒馆原生灰色。 */
    --theme-surface: #fffaf1;
    --theme-surface-muted: #f2e5d5;
    --theme-surface-disabled: #eadfce;
    --theme-text-primary: #4d3b32;
    --theme-text-secondary: #8b7668;
    --theme-text-disabled: #9a887a;
    --theme-border: #c6a069;
    --theme-focus-ring: #86aebb;
    --theme-opacity-disabled: 0.72;
    --theme-shadow: 0 5px 18px rgba(77, 59, 50, 0.08);
    --theme-code-inline-surface: #f2e5d5;
    --theme-code-block-surface: #fffaf1;
    --theme-code-text: #4d3b32;
    --theme-code-muted: #8b7668;
    --theme-code-accent: #7b98a5;
    --theme-code-selection: #dce7eb;
    --theme-code-overflow: auto;
    --theme-checkbox-indicator-content: "";
    --theme-checkbox-indicator-width: 0.58em;
    --theme-checkbox-indicator-height: 0.92em;
    --theme-checkbox-indicator-clip: polygon(14% 44%, 0 59%, 38% 100%, 100% 18%, 84% 0, 36% 68%);
    --theme-checkbox-indicator-transform-tail: translateZ(0);

    --cream-shell-bg: #f8f1e5;
    --cream-shell-paper: #fffaf1;
    --cream-shell-oat: #f2e5d5;
    --cream-shell-ink: #4d3b32;
    --cream-shell-muted: #8b7668;
    --cream-shell-blue: #a9c1ce;
    --cream-shell-pink: #d9b7af;
    --cream-shell-gold: #c6a069;
    --cream-shell-danger: #b56f6b;
    --cream-shell-focus: #86aebb;
    --cream-shell-line: rgba(166, 128, 75, 0.44);
    --cream-shell-line-soft: rgba(166, 128, 75, 0.24);
    --cream-shell-shadow: 0 10px 30px rgba(77, 59, 50, 0.10);
    --cream-shell-shadow-soft: 0 5px 18px rgba(77, 59, 50, 0.08);
    --cream-shell-radius-lg: 28px;
    --cream-shell-radius-md: 16px;
    --cream-shell-radius-sm: 10px;
    --cream-shell-font: "CreamShellSerif", "Songti SC", "STSong", "Noto Serif SC", serif;
    --cream-shell-texture: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/11ac346f90e0137af7ae68f0cad76c642409d6fa/assets/%E5%A5%B6%E6%B2%B9%E8%B4%9D%E5%A3%B3/cream-paper-texture.png");
    --cream-shell-user-fan: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/11ac346f90e0137af7ae68f0cad76c642409d6fa/assets/%E5%A5%B6%E6%B2%B9%E8%B4%9D%E5%A3%B3/user-fan-avatar-v6.png");
    --cream-shell-character-header-left: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/11ac346f90e0137af7ae68f0cad76c642409d6fa/assets/%E5%A5%B6%E6%B2%B9%E8%B4%9D%E5%A3%B3/character-header-left-v11.png");
    --cream-shell-character-header-center: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/11ac346f90e0137af7ae68f0cad76c642409d6fa/assets/%E5%A5%B6%E6%B2%B9%E8%B4%9D%E5%A3%B3/character-header-center-v11.png");
    --cream-shell-character-header-right: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/11ac346f90e0137af7ae68f0cad76c642409d6fa/assets/%E5%A5%B6%E6%B2%B9%E8%B4%9D%E5%A3%B3/character-header-right-v11.png");
    --cream-shell-character-footer-left: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/11ac346f90e0137af7ae68f0cad76c642409d6fa/assets/%E5%A5%B6%E6%B2%B9%E8%B4%9D%E5%A3%B3/character-footer-left-v11.png");
    --cream-shell-character-footer-center: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/11ac346f90e0137af7ae68f0cad76c642409d6fa/assets/%E5%A5%B6%E6%B2%B9%E8%B4%9D%E5%A3%B3/character-footer-center-v11.png");
    --cream-shell-character-footer-right: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/11ac346f90e0137af7ae68f0cad76c642409d6fa/assets/%E5%A5%B6%E6%B2%B9%E8%B4%9D%E5%A3%B3/character-footer-right-v11.png");
    --cream-shell-character-side-left: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/11ac346f90e0137af7ae68f0cad76c642409d6fa/assets/%E5%A5%B6%E6%B2%B9%E8%B4%9D%E5%A3%B3/character-side-left-v10.png");
    --cream-shell-character-side-right: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/11ac346f90e0137af7ae68f0cad76c642409d6fa/assets/%E5%A5%B6%E6%B2%B9%E8%B4%9D%E5%A3%B3/character-side-right-v10.png");
    --cream-shell-topbar-atlas: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/11ac346f90e0137af7ae68f0cad76c642409d6fa/assets/%E5%A5%B6%E6%B2%B9%E8%B4%9D%E5%A3%B3/topbar-atlas.png");
    --cream-shell-topbar-rail: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/11ac346f90e0137af7ae68f0cad76c642409d6fa/assets/%E5%A5%B6%E6%B2%B9%E8%B4%9D%E5%A3%B3/topbar-rail-tile-v9.png");
    --cream-shell-input-atlas: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/11ac346f90e0137af7ae68f0cad76c642409d6fa/assets/%E5%A5%B6%E6%B2%B9%E8%B4%9D%E5%A3%B3/input-atlas.png");
    --cream-shell-input-console: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/11ac346f90e0137af7ae68f0cad76c642409d6fa/assets/%E5%A5%B6%E6%B2%B9%E8%B4%9D%E5%A3%B3/input-console-v6.png");

    --SmartThemeBodyColor: #4d3b32;
    --SmartThemeEmColor: #8b7668;
    --SmartThemeQuoteColor: #7b98a5;
    --SmartThemeBlurTintColor: rgba(255, 250, 241, 0.96);
    --SmartThemeChatTintColor: rgba(248, 241, 229, 0.97);
    --SmartThemeBorderColor: rgba(166, 128, 75, 0.44);
    --SmartThemeShadowColor: rgba(77, 59, 50, 0.12);
    --SmartThemeBlurStrength: 0px;
    --shadowWidth: 0;
}

body {
    color: var(--cream-shell-ink);
    background-color: var(--cream-shell-bg);
    background-image: none;
}

#chat,
#send_form,
:is(#left-nav-panel, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup, .popup) {
    font-family: var(--cream-shell-font);
    font-weight: 400;
}


/* ===== src\chat-layout.css ===== */

/* v6 连续舞台：#chat 是持续场景；User 扇面与 Character 书页均属于逐消息正常流。 */

#chat {
    --avatar-size: 0px;
    --avatar-gap: 0px;
    --avatar-slot: 0px;
    position: relative;
    color: var(--cream-shell-ink);
    background-color: var(--cream-shell-bg);
    background-image:
        linear-gradient(rgba(255, 250, 241, 0.74), rgba(248, 241, 229, 0.92)),
        var(--cream-shell-texture);
    background-position: center, center;
    background-size: auto, 640px auto;
    background-repeat: no-repeat, repeat;
    background-attachment: local, local;
    border: 1px solid var(--cream-shell-line);
    border-top: 0;
    border-radius: 0 0 var(--cream-shell-radius-lg) var(--cream-shell-radius-lg);
    box-shadow:
        inset 0 0 0 4px rgba(255, 250, 241, 0.64),
        inset 0 0 0 5px var(--cream-shell-line-soft),
        var(--cream-shell-shadow);
    scrollbar-width: none;
    -ms-overflow-style: none;
}

#chat::-webkit-scrollbar {
    display: none;
    width: 0;
    height: 0;
}

#chat .mes {
    display: block;
    width: 100%;
    padding: clamp(10px, 1.4vw, 18px) 0;
    color: var(--cream-shell-ink);
    background: transparent;
    border: 0;
    box-shadow: none;
    container-type: inline-size;
}

/* 默认释放头像横向槽；只有 User 的真实头像在本条消息内部重新出现。 */
#chat .mes > .mesAvatarWrapper {
    display: none !important;
}

#chat .mes[is_user="true"] {
    position: relative;
}

#chat .mes[is_user="true"] > .mesAvatarWrapper {
    position: absolute;
    z-index: 4;
    top: clamp(52px, 7.6cqw, 78px);
    left: 50%;
    display: block !important;
    visibility: visible !important;
    width: clamp(82px, 10.8cqw, 112px);
    height: clamp(70px, 9.2cqw, 96px);
    min-height: 0;
    margin: 0;
    padding: 0;
    transform: translateX(-50%);
    pointer-events: none;
}

#chat .mes[is_user="true"] > .mesAvatarWrapper .avatar {
    display: block !important;
    visibility: visible !important;
    width: 100%;
    height: 100%;
    min-width: 0;
    min-height: 0;
    margin: 0;
    overflow: hidden;
    background: var(--cream-shell-paper);
    border: 2px solid rgba(198, 160, 105, 0.92);
    border-radius: 48% 48% 46% 46% / 46% 46% 54% 54%;
    box-shadow:
        0 0 0 3px rgba(255, 250, 241, 0.96),
        0 0 0 5px rgba(198, 160, 105, 0.52),
        0 6px 15px rgba(77, 59, 50, 0.16);
    filter: none;
    opacity: 1 !important;
}

#chat .mes[is_user="true"] > .mesAvatarWrapper .avatar img {
    display: block !important;
    visibility: visible !important;
    width: 100%;
    height: 100%;
    border-radius: inherit;
    object-fit: cover;
    object-position: center 40%;
    opacity: 1 !important;
}

#chat .mes[is_user="true"] > .mesAvatarWrapper > :not(.avatar) {
    display: none !important;
}

#chat .mes .mes_block {
    min-width: 0;
    margin: 0 auto;
    overflow: visible;
}

/* User：扇面本身就是消息外壳，真实头像嵌入顶部贝壳徽章。 */
#chat .mes[is_user="true"] .mes_block {
    position: relative;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    width: min(76%, 46rem);
    min-height: 0;
    aspect-ratio: 1533 / 1016;
    padding:
        clamp(9.8em, 18cqw, 12.4em)
        clamp(3.7em, 9cqw, 6.4em)
        clamp(10.6em, 24cqw, 14.4em);
    background-color: transparent;
    background-image: var(--cream-shell-user-fan);
    background-position: center top;
    background-repeat: no-repeat;
    background-size: 100% auto;
    border: 0;
    border-radius: 0;
    box-shadow: none;
}

/* Character：独立固定比例页首/页尾 + 自然延展纸面；中段不使用会变形的装饰图。 */
#chat .mes[is_user="false"][is_system="false"] .mes_block {
    position: relative;
    isolation: isolate;
    box-sizing: border-box;
    width: min(94%, 68rem);
    padding:
        clamp(9.4rem, 19.4cqw, 13.2rem)
        clamp(2.6em, 5.4cqw, 4.5em)
        clamp(7.2rem, 15.4cqw, 10.5rem);
    background-color: var(--cream-shell-paper);
    background-image:
        linear-gradient(rgba(255, 250, 241, 0.96), rgba(255, 248, 236, 0.97)),
        var(--cream-shell-character-side-left),
        var(--cream-shell-character-side-right),
        var(--cream-shell-texture);
    background-position:
        center,
        left top,
        right top,
        center;
    background-size:
        auto,
        clamp(34px, 4.4cqw, 48px) auto,
        clamp(34px, 4.4cqw, 48px) auto,
        560px auto;
    background-repeat:
        no-repeat,
        repeat-y,
        repeat-y,
        repeat;
    background-clip: padding-box;
    border: 1px solid rgba(166, 128, 75, 0.42);
    border-radius: 2px;
    box-shadow:
        inset 0 0 0 1px rgba(198, 160, 105, 0.28),
        0 16px 36px rgba(77, 59, 50, 0.10);
}

#chat .mes[is_user="false"][is_system="false"] .mes_block::before,
#chat .mes[is_user="false"][is_system="false"] .mes_block::after {
    content: "";
    position: absolute;
    right: -1px;
    left: -1px;
    z-index: 0;
    display: block;
    background-repeat: no-repeat;
    pointer-events: none;
}

#chat .mes[is_user="false"][is_system="false"] .mes_block::before {
    top: -1px;
    height: clamp(9.2rem, 19.4cqw, 13.2rem);
    background-image:
        var(--cream-shell-character-header-center),
        var(--cream-shell-character-header-left),
        var(--cream-shell-character-header-right),
        linear-gradient(90deg, transparent 2rem, rgba(166, 128, 75, 0.48) 2rem, rgba(166, 128, 75, 0.48) calc(100% - 2rem), transparent calc(100% - 2rem));
    background-position:
        center top,
        left 18%,
        right 18%,
        center 78%;
    background-size:
        auto 100%,
        auto 72%,
        auto 72%,
        100% 1px;
}

#chat .mes[is_user="false"][is_system="false"] .mes_block::after {
    bottom: -1px;
    height: clamp(7rem, 15.4cqw, 10.5rem);
    background-image:
        var(--cream-shell-character-footer-center),
        var(--cream-shell-character-footer-left),
        var(--cream-shell-character-footer-right),
        linear-gradient(90deg, transparent 2rem, rgba(166, 128, 75, 0.44) 2rem, rgba(166, 128, 75, 0.44) calc(100% - 2rem), transparent calc(100% - 2rem));
    background-position:
        center bottom,
        left 82%,
        right 82%,
        center 32%;
    background-size:
        auto 100%,
        auto 74%,
        auto 74%,
        100% 1px;
}

#chat .mes[is_user="false"][is_system="false"] .mes_block > * {
    position: relative;
    z-index: 1;
}

#chat .mes[is_system="true"],
#chat .smallSysMes {
    width: min(76%, 48rem);
    margin-inline: auto;
    color: #735e52;
    background: rgba(242, 229, 213, 0.90);
    border: 1px dashed rgba(166, 128, 75, 0.54);
    border-radius: var(--cream-shell-radius-sm);
}

#chat .mes .ch_name {
    align-items: baseline;
    gap: 0.6em;
    color: var(--cream-shell-ink);
}

#chat .mes[is_user="true"] .ch_name {
    position: relative;
    display: flex;
    width: min(68%, 32rem);
    justify-content: center;
    margin: 0 auto 0.3em;
    padding-top: 0.25em;
}

#chat .mes[is_user="true"] .ch_name > .flex-container:first-child {
    flex: 1 1 auto;
    min-width: 0;
    margin: 0;
    justify-content: center;
}

#chat .mes[is_user="true"] .ch_name > .flex-container:first-child > .flex-container {
    flex-wrap: nowrap;
    justify-content: center;
    align-items: baseline;
}

#chat .mes[is_user="true"] .ch_name :is(
    .name_text,
    .timestamp,
    .mesIDDisplay,
    .tokenCounterDisplay,
    .mes_timer
) {
    flex: 0 0 auto;
    white-space: nowrap;
}

/*
 * 动态姓名不能在不拆字、不加脚本的前提下沿 SVG 路径排版。
 * 这里让姓名与时间分别轻微抬落，形成顺着扇面展开的浅弧节奏，同时保留真实文字。
 */
#chat .mes[is_user="true"] .ch_name .name_text {
    transform: translateY(-0.16em) rotate(-2deg);
    transform-origin: right center;
}

#chat .mes[is_user="true"] .ch_name .timestamp {
    transform: translateY(0.08em) rotate(2deg);
    transform-origin: left center;
}

#chat .mes[is_user="true"] .ch_name .mes_buttons {
    position: absolute;
    top: 0.15em;
    right: 0;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name {
    display: flex;
    flex-wrap: nowrap;
    justify-content: center;
    margin: 0 0 1em;
    padding: 0.2em 0 0.76em;
    border-bottom: 1px solid rgba(166, 128, 75, 0.30);
}

#chat .mes[is_user="false"][is_system="false"] .ch_name :is(
    .name_text,
    .timestamp,
    .mesIDDisplay,
    .tokenCounterDisplay,
    .mes_timer,
    .mes_buttons
) {
    flex: 0 0 auto;
    white-space: nowrap;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name > .flex-container:first-child {
    flex: 0 1 auto;
    min-width: 0;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name > .flex-container:first-child > .flex-container {
    flex-wrap: nowrap;
    align-items: baseline;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name::before,
#chat .mes[is_user="false"][is_system="false"] .ch_name::after {
    content: "";
    flex: 1 1 54px;
    max-width: 112px;
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--cream-shell-gold));
}

#chat .mes[is_user="false"][is_system="false"] .ch_name::after {
    background: linear-gradient(90deg, var(--cream-shell-gold), transparent);
}

#chat .name_text {
    color: var(--cream-shell-ink);
    font-size: 1.05em;
    font-weight: 400;
    letter-spacing: 0.12em;
    text-shadow: none;
}

#chat .timestamp,
#chat .mesIDDisplay,
#chat .tokenCounterDisplay,
#chat .mes_timer {
    color: #80695b;
    font-size: 0.72em;
    opacity: 1;
    text-shadow: none;
}

#chat .mes_buttons {
    color: #9c7547;
    filter: none;
    text-shadow: none;
    opacity: 1;
    transition: color 160ms ease, transform 160ms ease;
}

#chat .mes_buttons :is(.mes_button, .fa-solid, .fa-regular) {
    color: inherit;
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#chat .mes:hover .mes_buttons,
#chat .mes:focus-within .mes_buttons {
    color: #6f8996;
}


/* ===== src\full-text.css ===== */

/* 长篇正文沿用酒馆字号缩放；层级使用相对单位，不把正文锁死为固定 px。 */

#chat .mes_text {
    max-width: 43rem;
    margin-inline: auto;
    padding: 0;
    color: var(--cream-shell-ink);
    font-size: clamp(0.94em, calc(0.87em + 0.18vw), 1.05em);
    line-height: 1.92;
    letter-spacing: 0.026em;
    overflow-wrap: anywhere;
}

#chat .mes[is_user="true"] .mes_text {
    position: relative;
    width: min(62%, 32rem);
    max-width: 32rem;
    min-height: 2.8em;
    margin-top: 0.12em;
    padding: 0.62em clamp(1.8em, 4.6cqw, 3.4em) 0.72em;
    background:
        radial-gradient(
            ellipse at 50% -35%,
            rgba(255, 250, 241, 0.74) 0 40%,
            rgba(255, 250, 241, 0.28) 64%,
            transparent 78%
        );
    border-radius: 50% 50% 38% 38% / 78% 78% 28% 28%;
    font-size: clamp(0.9em, calc(0.85em + 0.13vw), 1em);
    line-height: 1.58;
    letter-spacing: 0.055em;
    text-align: center;
    text-wrap: balance;
}

/* 用真实容器绘制弧形阅读带，不裁字、不改消息内容。 */
#chat .mes[is_user="true"] .mes_text::before {
    content: "";
    position: absolute;
    top: -0.18em;
    right: 12%;
    left: 12%;
    height: 1.1em;
    border-top: 1px solid rgba(166, 128, 75, 0.34);
    border-radius: 50% 50% 0 0 / 100% 100% 0 0;
    pointer-events: none;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text {
    position: relative;
    padding: clamp(0.35em, 0.75vw, 0.65em) 0;
}

/* 每段前的小爱心属于排版标记，不写进真实消息。 */
#chat .mes[is_user="false"][is_system="false"] .mes_text > p {
    margin: 0 0 1.08em;
    padding-left: 1.32em;
    text-indent: 0;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text > p::before {
    content: "♡";
    display: inline-block;
    width: 1em;
    margin-left: -1.18em;
    margin-right: 0.12em;
    color: #c98f8d;
    font-size: 0.78em;
    line-height: 1;
    text-align: center;
    text-shadow: 0 1px 0 rgba(255, 250, 241, 0.9);
}

#chat .mes_text :is(h1, h2, h3, h4) {
    position: relative;
    margin: 1.15em 0 0.72em;
    padding-bottom: 0.42em;
    color: var(--cream-shell-ink);
    border-bottom: 1px solid var(--cream-shell-line-soft);
    font-weight: 400;
    letter-spacing: 0.12em;
    line-height: 1.4;
    text-align: center;
    text-wrap: balance;
}

#chat .mes_text :is(h1, h2)::after {
    content: "❦";
    display: inline-block;
    margin-left: 0.72em;
    color: var(--cream-shell-gold);
    font-size: 0.62em;
    vertical-align: 0.18em;
}

#chat .mes_text h1 { font-size: 1.42em; }
#chat .mes_text h2 { font-size: 1.26em; }
#chat .mes_text :is(h3, h4) { font-size: 1.10em; }

#chat .mes_text :is(strong, b) {
    color: #775343;
    font-weight: 600;
}

#chat .mes_text :is(em, i) {
    color: #6f8996;
}

#chat .mes_text :is(blockquote, q) {
    color: #526f7e;
    text-shadow: none;
}

/* 引文改成参考图中的雾蓝丝带。 */
#chat .mes_text blockquote {
    position: relative;
    margin: 1.3em 0;
    padding: 0.78em 2.2em 0.84em;
    color: #526f7e;
    background:
        linear-gradient(90deg,
            rgba(119, 152, 168, 0.82),
            rgba(211, 225, 230, 0.92) 10%,
            rgba(239, 232, 219, 0.96) 50%,
            rgba(211, 225, 230, 0.92) 90%,
            rgba(119, 152, 168, 0.82));
    border: 1px solid rgba(166, 128, 75, 0.44);
    border-radius: 2px;
    box-shadow:
        inset 0 0 0 2px rgba(255, 250, 241, 0.62),
        0 4px 10px rgba(77, 59, 50, 0.08);
    text-align: center;
}

#chat .mes_text blockquote::before,
#chat .mes_text blockquote::after {
    content: "◆";
    position: absolute;
    top: 50%;
    color: rgba(198, 160, 105, 0.86);
    font-size: 0.56em;
    transform: translateY(-50%);
}

#chat .mes_text blockquote::before { left: 0.9em; }
#chat .mes_text blockquote::after { right: 0.9em; }

#chat .mes_text :is(ul, ol) {
    margin: 0.8em 0 1em 1.35em;
    padding-left: 0.8em;
}

#chat .mes_text li {
    margin-block: 0.32em;
    padding-left: 0.18em;
}

#chat .mes_text li::marker {
    color: var(--cream-shell-gold);
}

#chat .mes_text hr {
    height: 1.2em;
    margin: 1.35em auto;
    border: 0;
    background:
        linear-gradient(90deg, transparent, var(--cream-shell-line) 30%, var(--cream-shell-line) 70%, transparent)
        center / 100% 1px no-repeat;
}

#chat .mes_text :is(pre, code) {
    font-family: "Cascadia Mono", "SFMono-Regular", Consolas, monospace;
}

#chat .mes_text code {
    color: #6d5460;
    background: rgba(217, 183, 175, 0.18);
    border: 1px solid rgba(181, 111, 107, 0.20);
    border-radius: 0.35em;
}

#chat .mes_text pre {
    padding: 0.95em 1.05em;
    color: var(--cream-shell-ink);
    background: rgba(242, 229, 213, 0.82);
    border: 1px solid var(--cream-shell-line-soft);
    border-radius: 3px 14px 3px 14px;
    box-shadow: inset 0 0 0 3px rgba(255, 250, 241, 0.54);
    overflow: auto;
}

#chat .mes_text :is(img, video, audio, iframe, table) {
    max-width: 100%;
}

#chat .mes_text :is(img, video) {
    border: 1px solid var(--cream-shell-line);
    border-radius: 3px 18px 3px 18px;
    box-shadow:
        0 0 0 4px rgba(255, 250, 241, 0.72),
        var(--cream-shell-shadow-soft);
}

#chat .mes_text table {
    border-collapse: separate;
    border-spacing: 0;
    background: rgba(255, 250, 241, 0.82);
    border: 1px solid var(--cream-shell-line);
}

#chat .mes_text :is(th, td) {
    padding: 0.56em 0.72em;
    border-right: 1px solid var(--cream-shell-line-soft);
    border-bottom: 1px solid var(--cream-shell-line-soft);
}

#chat .mes_text th {
    color: var(--cream-shell-ink);
    background: linear-gradient(90deg, rgba(169, 193, 206, 0.22), rgba(217, 183, 175, 0.18));
    font-weight: 400;
    letter-spacing: 0.06em;
}

/* 推理/思考折叠块：覆盖真正持有原生灰底的 header，而不只改 summary 外壳。 */
#chat .mes_reasoning_details {
    margin: 0.95em 0 1.15em;
    color: #5f7884;
    background:
        linear-gradient(90deg, rgba(169, 193, 206, 0.18), rgba(255, 250, 241, 0.96), rgba(217, 183, 175, 0.16));
    border: 1px solid rgba(166, 128, 75, 0.44);
    border-radius: 3px 18px 3px 18px;
    box-shadow:
        inset 0 0 0 3px rgba(255, 250, 241, 0.68),
        0 5px 14px rgba(77, 59, 50, 0.07);
    filter: none;
    overflow: clip;
}

#chat .mes_reasoning_details .mes_reasoning_summary {
    margin-right: 0;
    padding: 0.55em 0.7em;
    color: #526f7e;
    background: transparent;
    filter: none;
    text-shadow: none;
}

#chat .mes_reasoning_details .mes_reasoning_header {
    margin: 0;
    padding: 0.58em 2.1em 0.58em 1em;
    color: #526f7e;
    background:
        linear-gradient(90deg, rgba(169, 193, 206, 0.50), rgba(255, 250, 241, 0.92) 62%, rgba(217, 183, 175, 0.22)) !important;
    border: 1px solid rgba(166, 128, 75, 0.34);
    border-radius: 2px 13px 2px 13px;
    box-shadow: inset 0 0 0 2px rgba(255, 250, 241, 0.66);
    filter: none !important;
    opacity: 1;
    text-shadow: none;
}

#chat .mes_reasoning_details[data-state="thinking"] .mes_reasoning_header {
    background:
        linear-gradient(90deg, rgba(134, 174, 187, 0.54), rgba(255, 250, 241, 0.94) 66%, rgba(217, 183, 175, 0.24)) !important;
}

#chat .mes_reasoning_header_title {
    color: #526f7e;
    font-weight: 400;
    letter-spacing: 0.07em;
    opacity: 1;
    text-shadow: none;
}

#chat .mes_reasoning_details .mes_reasoning_arrow {
    color: #9c7547;
    filter: none;
    text-shadow: none;
}

#chat .mes_reasoning {
    margin: 0;
    padding: 0.9em 1.15em 1.05em;
    color: var(--cream-shell-ink);
    background: rgba(255, 250, 241, 0.72);
    border: 0;
    border-top: 1px solid rgba(166, 128, 75, 0.22);
    filter: none;
    text-shadow: none;
}

#chat .mes_reasoning_actions,
#chat .mes_reasoning_actions :is(.mes_button, .edit_button) {
    color: #80695b;
    background: transparent;
    filter: none;
    opacity: 1;
    text-shadow: none;
}

#chat .reasoning_edit_textarea {
    color: var(--cream-shell-ink);
    background: rgba(255, 250, 241, 0.94);
    border: 1px solid var(--cream-shell-line);
    box-shadow: none;
}


/* ===== src\windows\topbar.css ===== */

/* v6 顶栏：九个真实入口落在同一根连续横梁上；不改抽屉几何。 */

#top-bar {
