    display: none !important;
}

:is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder):is(:hover, :focus-within) .drawer-icon,
:is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) .drawer-icon.openIcon {
