}

#ai-config-button .drawer-icon::after { background-position: 0% 0%; }
#sys-settings-button .drawer-icon::after { background-position: 50% 0%; }
#advanced-formatting-button .drawer-icon::after { background-position: 100% 0%; }
#WI-SP-button .drawer-icon::after { background-position: 0% 50%; }
#user-settings-button .drawer-icon::after { background-position: 50% 50%; }
#backgrounds-button .drawer-icon::after { background-position: 100% 50%; }
