#persona-management-button .drawer-icon::after { background-position: 50% 100%; }
#rightNavHolder .drawer-icon::after { background-position: 100% 100%; }


/* ===== src\windows\input.css ===== */

/* v7 输入台：外层完全透明；Quick Reply、菜单、魔法棒、textarea 与发送/停止属于同一座台面。 */

#form_sheld {
    background-color: var(--cream-shell-bg) !important;
    background-image: none !important;
    border: 0;
    box-shadow: none;
    backdrop-filter: none;
}

#send_form {
    position: relative;
    box-sizing: border-box;
    width: 100%;
    margin-inline: 0;
    color: var(--cream-shell-ink);
    background: transparent !important;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    backdrop-filter: none;
}

#send_form #qr--bar {
    position: relative;
    z-index: 3;
    box-sizing: border-box;
    flex: 0 0 100%;
    width: 84%;
    top: clamp(44px, 4vw, 58px);
    min-height: 28px;
    margin: 0 8% clamp(-58px, -4vw, -44px);
    padding: 2px clamp(4%, 6vw, 8%) 0;
    gap: 0.35em;
    overflow-x: auto;
    overflow-y: hidden;
    flex-wrap: nowrap;
    background: transparent;
    scrollbar-width: none;
}

#send_form #qr--bar::-webkit-scrollbar {
    display: none;
}

#send_form #nonQRFormItems {
    position: relative;
    isolation: isolate;
    box-sizing: border-box;
    flex: 0 0 100%;
    display: grid;
    grid-template-columns: 8% 19% minmax(0, 46%) 19% 8%;
    width: 100%;
    max-width: 100%;
    min-height: clamp(178px, 17vw, 245px);
    margin: -8px 0 0;
    inset-inline: 0;
    transform: none;
    padding: clamp(24px, 3vw, 38px) 0;
    column-gap: 0;
    align-items: center;
    background: transparent;
    border: 0;
}

#send_form #nonQRFormItems::before {
    content: "";
    display: block;
    position: absolute;
    z-index: 0;
    inset: 50% 8% auto;
    height: auto;
    aspect-ratio: 1822 / 393;
    background-image: var(--cream-shell-input-console);
    background-position: center;
    background-repeat: no-repeat;
    background-size: 100% 100%;
    transform: translateY(-50%);
    pointer-events: none;
}

#send_form #nonQRFormItems > * {
    position: relative;
    z-index: 1;
}

#send_form :is(#leftSendForm, #rightSendForm) {
    width: 100%;
    justify-content: center;
    align-items: center;
    gap: clamp(8px, 1.2vw, 16px);
    padding: 0;
}

#send_form #leftSendForm {
    grid-column: 2;
}

#send_form #send_textarea {
    grid-column: 3;
}

#send_form #rightSendForm {
    grid-column: 4;
}

#send_form #send_textarea {
    min-width: 0;
    min-height: clamp(46px, 4.1vw, 62px);
    height: clamp(46px, 4.1vw, 62px);
    max-height: min(28vh, 14rem);
    margin: 0;
    padding: 0.58em clamp(1.4em, 2.4vw, 2.6em);
    color: var(--cream-shell-ink);
    background: rgba(255, 250, 241, 0.26);
    border: 0;
    border-top: var(--progWidth) solid transparent;
    border-radius: 0;
    box-shadow: none;
    clip-path: polygon(3% 0, 97% 0, 100% 16%, 100% 84%, 97% 100%, 3% 100%, 0 84%, 0 16%);
    font-family: var(--cream-shell-font);
    font-size: calc(var(--mainFontSize) * 0.94);
    line-height: 1.45;
    text-shadow: none;
    resize: vertical;
}

#send_form:has(#send_textarea:focus-visible) {
    border-color: transparent;
    outline: 0;
}

#send_form #send_textarea:focus-visible {
    background: rgba(255, 250, 241, 0.48);
    border-top-color: rgba(134, 174, 187, 0.58);
    box-shadow: inset 0 0 0 1px rgba(134, 174, 187, 0.26);
}

#send_form #send_textarea::placeholder {
    color: var(--cream-shell-muted) !important;
    opacity: 0.74;
}

#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #stscript_stop) {
    position: relative;
    flex: 0 0 clamp(40px, 4.2vw, 54px);
    width: clamp(40px, 4.2vw, 54px);
    height: clamp(40px, 4.2vw, 54px);
    min-width: 0;
    color: var(--cream-shell-muted);
    font-size: 0;
    filter: none;
    text-shadow: none;
    opacity: 1;
}

#send_form :is(#mes_stop, #stscript_stop) > i {
    color: transparent;
    font-size: 0;
}

#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #stscript_stop)::after {
    content: "";
    display: block;
    position: absolute;
    z-index: 1;
    inset: 0;
    background-color: transparent;
    background-image: var(--cream-shell-input-atlas);
    background-size: 400% 100%;
    background-repeat: no-repeat;
    filter: none;
    pointer-events: none;
}

#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #stscript_stop)::before {
    content: none !important;
    display: none !important;
}

#send_form #options_button::after { background-position: 0% 50%; }
#send_form #extensionsMenuButton::after { background-position: 33.333% 50%; }
#send_form #send_but::after { background-position: 66.667% 50%; }
#send_form :is(#mes_stop, #stscript_stop)::after { background-position: 100% 50%; }

#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #stscript_stop):hover {
    transform: scale(1.045);
}

#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #stscript_stop):focus-visible {
    outline: 2px solid var(--cream-shell-focus);
    outline-offset: 2px;
    border-radius: 50%;
}

#send_form.no-connection #send_textarea::placeholder {
    color: var(--cream-shell-danger) !important;
}

#send_form .qr--button {
    flex: 0 0 auto;
    min-height: 25px;
    padding: 0.18em 0.68em;
    color: #735e52;
    background: rgba(255, 250, 241, 0.90);
    border: 1px solid rgba(166, 128, 75, 0.40);
    border-radius: 999px;
    box-shadow: inset 0 0 0 2px rgba(255, 250, 241, 0.64);
    text-shadow: none;
    opacity: 1;
}

#send_form .qr--button:hover {
    color: #536f7d;
    background: rgba(220, 231, 235, 0.94);
}


/* ===== src\windows\forms-shared.css ===== */

