:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup) :is(h1, h2, h3, h4, h5, .standoutHeader) {
