:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup) :is(.inline-drawer-header, .standoutHeader, h4.standoutHeader) {
