#chat :is(.mes_button, .edit_button, .mes_edit, .mes_more):disabled {
    color: var(--theme-text-disabled);
    opacity: var(--theme-opacity-disabled);
    filter: none;
    text-shadow: none;
    box-shadow: none;
}

#chat :is(.mes_button, .edit_button, .mes_edit, .mes_more):focus-visible {
    color: var(--theme-text-primary);
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: 2px;
}

/* 顶栏与输入动作 */
#top-settings-holder .drawer-icon,
#top-settings-holder .drawer-icon:hover,
#top-settings-holder .drawer-icon.openIcon,
#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #stscript_stop) {
    color: var(--theme-text-secondary);
    opacity: 1;
    filter: none;
    text-shadow: none;
    box-shadow: none;
}

#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #stscript_stop):disabled {
    color: var(--theme-text-disabled);
    opacity: var(--theme-opacity-disabled);
    filter: none;
    text-shadow: none;
    box-shadow: none;
}

#top-settings-holder .drawer-icon:focus-visible,
#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #stscript_stop):focus-visible {
    color: var(--theme-text-primary);
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: 2px;
}

/* 抽屉标题 */
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) :is(.inline-drawer-header, .standoutHeader, h4),
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) :is(.inline-drawer-header, .standoutHeader, h4).open,
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) :is(.inline-drawer-header, .standoutHeader, h4).closed {
    color: var(--theme-text-primary);
    background: var(--theme-surface-muted);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) :is(.inline-drawer-header, .standoutHeader, h4).disabled {
    color: var(--theme-text-disabled);
    background: var(--theme-surface-disabled);
    border: 1px solid var(--theme-border);
    opacity: var(--theme-opacity-disabled);
    filter: none;
    text-shadow: none;
}

:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) .inline-drawer-icon {
    color: var(--theme-text-secondary);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* Toast / 通知 */
#toast-container :is(.toast-info, .toast-success, .toast-warning, .toast-error, .toast-loading),
.toast:is(.toast-info, .toast-success, .toast-warning, .toast-error, .toast-loading) {
    color: var(--theme-text-primary);
    background: var(--theme-surface);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    box-shadow: var(--theme-shadow);
}

#toast-container :is(.toast-title, .toast-message, .toast-close-button),
.toast :is(.toast-title, .toast-message, .toast-close-button) {
    color: var(--theme-text-primary);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#toast-container :is(.toast-close-button, button):focus-visible,
.toast :is(.toast-close-button, button):focus-visible {
    color: var(--theme-text-primary);
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: 2px;
}

/* 独立弹层 */
:is(.popup, .popup-content, .modal-content, .dialogue_popup),
:is(.popup, .popup-content, .modal-content, .dialogue_popup) :is(.menu_button, button, [role="option"]),
:is(.popup, .popup-content, .modal-content, .dialogue_popup) :is(.menu_button, button, [role="option"]):hover,
:is(.popup, .popup-content, .modal-content, .dialogue_popup) :is(.menu_button, button, [role="option"]).selected {
    color: var(--theme-text-primary);
    background: var(--theme-surface);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    box-shadow: var(--theme-shadow);
}

:is(.popup, .popup-content, .modal-content, .dialogue_popup) :is(.menu_button, button, [role="option"]):disabled {
    color: var(--theme-text-disabled);
    background: var(--theme-surface-disabled);
    border-color: var(--theme-border);
    opacity: var(--theme-opacity-disabled);
    filter: none;
    box-shadow: none;
}

:is(.popup, .popup-content, .modal-content, .dialogue_popup) :is(.menu_button, button, [role="option"]):focus-visible {
    color: var(--theme-text-primary);
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: 2px;
}

:is(.popup, .popup-content, .modal-content, .dialogue_popup) :is(.popup-body, .dialogue_popup_text),
:is(.popup, .popup-content, .modal-content, .dialogue_popup) :is(.fa, .fa-solid, .fa-regular) {
    color: var(--theme-text-primary);
    opacity: 1;
    filter: none;
    text-shadow: none;
}


/* ===== src\windows\mobile.css ===== */

/* v6 手机独立母版：取消复杂侧景，书页与扇面全宽，抽屉仍由官方负责。 */

@media (max-width: 1000px) {
    #chat {
        background-image:
            linear-gradient(90deg,
                rgba(198, 160, 105, 0.18) 0 3px,
                transparent 3px calc(100% - 3px),
                rgba(198, 160, 105, 0.18) calc(100% - 3px)),
            linear-gradient(rgba(255, 250, 241, 0.88), rgba(248, 241, 229, 0.96)),
            var(--cream-shell-texture);
        background-size: auto, auto, 520px auto;
        background-repeat: no-repeat, no-repeat, repeat;
        border-inline: 0;
        border-radius: 0;
        box-shadow: none;
    }

    #chat .mes,
    #chat .mes:first-child {
        padding: 9px clamp(5px, 2.4vw, 12px);
    }

    #chat .mes[is_user="true"] > .mesAvatarWrapper {
        top: clamp(28px, 8.6vw, 38px);
        width: clamp(52px, 14.5vw, 64px);
        height: clamp(44px, 12vw, 54px);
    }

    #chat .mes[is_user="true"] .mes_block {
        width: calc(100% - 10px);
        min-height: 0;
        aspect-ratio: 1533 / 1016;
        padding:
            clamp(5.5em, 23vw, 6.4em)
            clamp(1.6em, 8vw, 2.6em)
            clamp(6.1em, 27vw, 7.3em);
        background-position: center top;
        background-size: 100% auto;
    }

    #chat .mes[is_user="false"][is_system="false"] .mes_block {
        width: calc(100% - 8px);
        box-sizing: border-box;
        padding:
            clamp(4.7rem, 20vw, 6.2rem)
            clamp(1em, 4.5vw, 1.5em)
            clamp(3.8rem, 16vw, 5rem);
        box-shadow: 0 8px 18px rgba(77, 59, 50, 0.08);
        background-size:
            auto,
            clamp(24px, 8vw, 34px) auto,
            clamp(24px, 8vw, 34px) auto,
            520px auto;
    }

    #chat .mes[is_user="false"][is_system="false"] .mes_block::before {
        height: clamp(4.5rem, 20vw, 6.2rem);
        background-size:
            auto 88%,
            auto 54%,
            auto 54%,
            100% 1px;
    }

    #chat .mes[is_user="false"][is_system="false"] .mes_block::after {
        height: clamp(3.7rem, 16vw, 5rem);
        background-size:
            auto 88%,
            auto 56%,
            auto 56%,
            100% 1px;
    }

    #chat .mes_text {
        max-width: none;
        font-size: clamp(0.93em, calc(0.90em + 0.12vw), 1em);
        line-height: 1.78;
    }

    #chat .mes[is_user="false"][is_system="false"] .mes_text > p {
        padding-left: 1.22em;
    }

    #chat .mes[is_user="true"] .ch_name {
        flex-wrap: wrap;
        row-gap: 0.18em;
    }

    #top-settings-holder {
        background-size: auto 100%;
        background-repeat: repeat-x;
    }

    :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) {
        padding: 0;
    }

    :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) .drawer-icon {
        width: clamp(29px, 8.6vw, 38px);
        height: clamp(29px, 8.6vw, 38px);
    }

    #send_form #qr--bar {
        top: 30px;
        min-height: 28px;
        width: 94%;
        margin-inline: 3%;
        margin-bottom: -30px;
        padding-inline: 1.1em;
    }

    #send_form #nonQRFormItems {
        grid-template-columns: 3% 22% minmax(0, 50%) 22% 3%;
        min-height: clamp(82px, 24vw, 106px);
        padding: clamp(17px, 5vw, 22px) 0;
    }

    #send_form #nonQRFormItems::before {
        left: 3%;
        right: 3%;
        background-size: 100% 100%;
    }

    #send_form :is(#leftSendForm, #rightSendForm) {
        width: 100%;
    }

    #send_form #send_textarea {
        min-height: clamp(42px, 12vw, 54px);
        height: clamp(42px, 12vw, 54px);
        padding: 0.5em clamp(0.75em, 3.5vw, 1.35em);
        font-size: calc(var(--mainFontSize) * 0.92);
    }

    #send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #stscript_stop) {
        flex-basis: clamp(38px, 11vw, 48px);
        width: clamp(38px, 11vw, 48px);
        height: clamp(38px, 11vw, 48px);
    }

    :is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) {
        border-inline: 0;
        border-radius: 0;
        box-shadow: none;
    }

    #PersonaManagement #persona-management-block,
    #rm_extensions_block .extensions_block {
        gap: 0.7rem;
    }

    #completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
        padding: 0.62em;
    }
}

@media (max-width: 430px) {
    #chat .mes_text {
        letter-spacing: 0.012em;
    }

    #chat .timestamp,
    #chat .mesIDDisplay,
    #chat .tokenCounterDisplay,
    #chat .mes_timer {
        font-size: 0.68em;
    }
}

@media (max-width: 700px) {
    #chat .mes[is_user="false"][is_system="false"] {
        display: flex;
        flex-direction: column;
        width: 100%;
    }

    #chat .mes[is_user="false"][is_system="false"] > .mes_block {
        width: 100%;
        min-width: 0;
    }

    #chat .mes[is_user="false"][is_system="false"] > .mes_block > .mes_text {
        box-sizing: border-box;
        width: 100%;
        margin-inline: auto;
        padding-inline: clamp(1.2em, 5vw, 1.8em);
    }
}

@media (max-width: 390px) {
    #chat .mes {
        padding-inline: 4px;
    }

    #chat .mes_reasoning_details .mes_reasoning_summary {
        padding-inline: 0.45em;
    }

    #send_form #send_textarea {
        padding-right: 1.1em;
    }
}

@media (max-width: 360px) {
    :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) .drawer-icon {
        width: 28px;
        height: 28px;
    }

    #send_form #send_textarea {
        padding-inline: 0.35em 0.85em;
    }
}


/* ===== src\fallback.css ===== */

/* 远程素材失败时，纯色、文字和原生图标仍保持可用。 */

@supports not (background-image: image-set(url("") 1x)) {
    #chat,
    :is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup) {
        background-image: none;
        background-color: var(--cream-shell-paper);
    }
}

@media (forced-colors: active) {
    #chat,
    #send_form,
    #top-bar,
    #top-settings-holder,
    :is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup) {
        border-color: CanvasText;
        box-shadow: none;
    }

    #top-settings-holder .drawer-icon::after,
    #send_form #options_button::after,
    #send_form #extensionsMenuButton::after,
    #send_form #send_but::after,
    #send_form #mes_stop::after,
    #send_form #stscript_stop::after,
    #send_form #nonQRFormItems::before {
        display: none;
    }

    #chat {
        background-image: none;
    }

    #top-settings-holder {
        background-image: none;
    }

    #chat .mes[is_user="true"] .mes_block,
    #chat .mes[is_user="false"][is_system="false"] .mes_block {
        background-image: none;
        border-color: CanvasText;
    }

    #top-settings-holder .drawer-icon {
        color: CanvasText;
        font-size: var(--topBarIconSize, 1rem);
    }

    #send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #stscript_stop) {
        color: CanvasText;
        font-size: var(--bottomFormIconSize, 1rem);
    }

    #send_form :is(#mes_stop, #stscript_stop) > i {
        color: CanvasText;
        font-size: inherit;
    }

    #send_form #nonQRFormItems::before {
        display: none;
    }
}
